import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"华为设备安装（历史存档）","description":"","frontmatter":{},"headers":[],"relativePath":"archive/huawei-install.md","filePath":"archive/huawei-install.md","lastUpdated":1792939073000}`),a={name:`archive/huawei-install.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="华为设备安装-历史存档" tabindex="-1">华为设备安装（历史存档） <a class="header-anchor" href="#华为设备安装-历史存档" aria-label="Permalink to “华为设备安装（历史存档）”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">存档说明</p><p>华为设备的安装说明已于 2021 年从 Magisk 官方文档中移除。本页内容还原自 <a href="https://github.com/topjohnwu/Magisk/blob/408399eae095b7cbd3e05278682c4bb4c7702ec0/docs/install.md" target="_blank" rel="noreferrer">2021-03-22 的上游文档</a>，仅供历史参考。当前版本的 Magisk 已不再正式支持这些设备，请以官方最新文档为准。</p></div><p>Magisk 不再正式支持现代华为设备，因为其设备上的 bootloader 无法通过官方途径解锁，更重要的是它们不遵循标准的 Android 分区方案。以下只是一些一般性指导。</p><p>使用麒麟（Kirin）处理器的华为设备与大多数常见设备的分区方式不同。Magisk 通常安装在设备的 <code>boot</code> 分区中，但华为设备没有该分区。</p><p>通常请按照<a href="./../install.html#修补映像">修补映像</a>的步骤操作，但与原说明有以下区别：</p><ul><li>下载固件 zip 后（可以在 <a href="http://pro-teammt.ru/firmware-database/" target="_blank" rel="noreferrer">Huawei Firmware Database</a> 中找到许多固件），您需要使用 <a href="https://forum.xda-developers.com/showthread.php?t=2433454" target="_blank" rel="noreferrer">Huawei Update Extractor</a>（仅限 Windows！）从 zip 中的 <code>UPDATE.APP</code> 提取映像。</li><li>关于修补映像： <ul><li>如果您的设备有启动 ramdisk，请修补 <code>RAMDISK.img</code>，而不是 <code>boot.img</code></li><li>如果您的设备<strong>没有</strong>启动 ramdisk，请修补 <code>RECOVERY_RAMDIS.img</code>（这不是拼写错误），而不是 <code>recovery.img</code></li></ul></li><li>使用 <code>fastboot</code> 刷回映像时： <ul><li>如果修补的是 <code>RAMDISK.img</code>，请使用命令 <code>fastboot flash ramdisk magisk_patched.img</code> 刷入</li><li>如果修补的是 <code>RECOVERY_RAMDIS.img</code>，请使用命令 <code>fastboot flash recovery_ramdisk magisk_patched.img</code> 刷入</li></ul></li></ul><details class="details custom-block"><summary>英文原版</summary><h2 id="huawei" tabindex="-1">Huawei <a class="header-anchor" href="#huawei" aria-label="Permalink to “Huawei”">​</a></h2><p>Magisk no longer officially support modern Huawei devices as the bootloader on their devices are not unlockable, and more importantly they do not follow standard Android partitioning schemes. The following are just some general guidance.</p><p>Huawei devices using Kirin processors have a different partitioning method from most common devices. Magisk is usually installed to the <code>boot</code> partition of the device, however Huawei devices do not have this partition.</p><p>Generally, follow <a href="https://github.com/topjohnwu/Magisk/blob/408399eae095b7cbd3e05278682c4bb4c7702ec0/docs/install.md#patching-images" target="_blank" rel="noreferrer">Patching Images</a> with some differences from the original instructions:</p><ul><li>After downloading your firmware zip (you may find a lot in <a href="http://pro-teammt.ru/firmware-database/" target="_blank" rel="noreferrer">Huawei Firmware Database</a>), you have to extract images from <code>UPDATE.APP</code> in the zip with <a href="https://forum.xda-developers.com/showthread.php?t=2433454" target="_blank" rel="noreferrer">Huawei Update Extractor</a> (Windows only!)</li><li>Regarding patching images: <ul><li>If your device has boot ramdisk, patch <code>RAMDISK.img</code> instead of <code>boot.img</code></li><li>If your device does <strong>NOT</strong> have boot ramdisk, patch <code>RECOVERY_RAMDIS.img</code> (this is not a typo) instead of <code>recovery.img</code></li></ul></li><li>When flashing the image back with <code>fastboot</code><ul><li>If you patched <code>RAMDISK.img</code>, flash with command <code>fastboot flash ramdisk magisk_patched.img</code></li><li>If you patched <code>RECOVERY_RAMDIS.img</code>, flash with command <code>fastboot flash recovery_ramdisk magisk_patched.img</code></li></ul></li></ul></details><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h2><ul><li><a href="https://github.com/topjohnwu/Magisk/blob/408399eae095b7cbd3e05278682c4bb4c7702ec0/docs/install.md" target="_blank" rel="noreferrer">Magisk 安装说明（2021-03-22 存档）</a>（官方历史版本）</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};